SELECT CASE WHEN accounts.status IN ('OPEN', 'CLOSED') THEN 'group_a' ELSE 'other' END AS status_group, accounts.status, SUM(CASE WHEN transactions.txn_type = 'DEBIT' THEN transactions.amount ELSE 0 END) AS debit_amount FROM transactions INNER JOIN accounts ON transactions.account_id = accounts.id LEFT JOIN customers ON accounts.customer_id = customers.id WHERE accounts.balance BETWEEN 34000 AND 67000 GROUP BY CASE WHEN accounts.status IN ('OPEN', 'CLOSED') THEN 'group_a' ELSE 'other' END, accounts.status ORDER BY debit_amount
